<script setup>
import {computed,ref,watch} from 'vue'
import {ticTacToeExamples,ticTacToeTerminal,ticTacToeTurn,ticTacToeFeatures,analyzeTicTacToe,validateTicTacToe} from '../services/tic-tac-toe.mjs'
import {ticTacToeCode} from '../services/tic-tac-toe-code.mjs'
const ticTacToeSource=ticTacToeCode.join('\n')
const preset=ref('empty'),board=ref(Array(9).fill('')),mode=ref('alphabeta'),depth=ref(9),history=ref([]),input=ref('.........'),error=ref(''),w1=ref(1),w2=ref(4),copied=ref(false)
watch(preset,()=>{board.value=[...ticTacToeExamples.find(e=>e.id===preset.value).board];history.value=[];error.value='';input.value=board.value.map(v=>v||'.').join('')})
const end=computed(()=>ticTacToeTerminal(board.value)),turn=computed(()=>ticTacToeTurn(board.value))
const result=computed(()=>analyzeTicTacToe(board.value,mode.value,depth.value,[w1.value,w2.value]))
const features=computed(()=>ticTacToeFeatures(board.value,[w1.value,w2.value]))
function play(i){if(end.value.done||board.value[i])return;history.value.push([...board.value]);const next=[...board.value];next[i]=turn.value;board.value=next;error.value=''}
function undo(){if(history.value.length)board.value=history.value.pop()}
function reset(){board.value=[...ticTacToeExamples.find(e=>e.id===preset.value).board];history.value=[]}
function apply(){try{const a=input.value.trim().toUpperCase().replace(/[\s,]/g,'').split('').map(v=>v==='.'||v==='0'?'':v);validateTicTacToe(a);board.value=a;history.value=[];error.value=''}catch(e){error.value=e.message}}
async function copy(){try{await navigator.clipboard.writeText(ticTacToeSource);copied.value=true}catch{error.value='Chưa chép được mã. Bạn có thể chọn mã bên dưới.'}}
function tokens(row){return row.split(/('(?:[^'\\]|\\.)*'|\b(?:export|function|const|let|for|of|if|else|return|while|yield|continue|break|new|true|false|null)\b|\b\d+\b)/g).filter(Boolean).map(text=>({text,kind:text.startsWith("'")?'string':/^(export|function|const|let|for|of|if|else|return|while|yield|continue|break|new|true|false|null)$/.test(text)?'keyword':/^\d/.test(text)?'number':''}))}
</script>

<template>
<figure class="lab ttt-lab" aria-label="Chơi tic tac toe và xem các giá trị Minimax của từng nước">
 <div class="ttt-settings"><label>Thế cờ<select v-model="preset"><option v-for="e in ticTacToeExamples" :key="e.id" :value="e.id">{{ e.title }}</option></select></label><label>Thuật toán<select v-model="mode"><option value="alphabeta">Alpha–Beta</option><option value="minimax">Minimax</option></select></label><label>Độ sâu<input v-model.number="depth" type="range" min="1" max="9"/>{{ depth }} hành động, tính cả nước đang chọn</label></div>
 <p class="ttt-status" role="status"><template v-if="end.done">{{ end.winner?end.winner+' đã thắng.':'Ván đấu hòa.' }} Lợi ích của MAX: {{ end.value }}.</template><template v-else>Lượt {{ turn }} · {{ turn==='X'?'MAX chọn giá trị lớn nhất':'MIN chọn giá trị nhỏ nhất' }}. Giá trị tìm kiếm: {{ result.value }}. Đề nghị ô {{ result.bestMove+1 }}.</template></p>
 <div class="ttt-panels"><section><h4>Bàn cờ · X là MAX, O là MIN</h4><div class="ttt-board" role="group" aria-label="Bàn cờ chín ô"><button v-for="(v,i) in board" :key="i" type="button" :disabled="!!v||end.done" :aria-label="`Ô ${i+1}: ${v||'Trống'}`" :class="{recommended:i===result.bestMove,winning:end.line.includes(i)}" @click="play(i)">{{ v||i+1 }}</button></div><div class="ttt-actions"><button type="button" :disabled="result.bestMove===null" @click="play(result.bestMove)">Đi nước đề nghị</button><button type="button" :disabled="!history.length" @click="undo">Lùi nước</button><button type="button" @click="reset">Đặt lại</button></div></section>
 <section class="ttt-moves"><h4>Giá trị của từng hành động</h4><ol><li v-for="m in result.moves" :key="m.move">Ô {{ m.move+1 }}: {{ m.value }}<strong v-if="m.move===result.bestMove"> · Đề nghị</strong></li></ol><p>+100: X thắng. −100: O thắng. 0 tại trạng thái kết thúc: Hòa. Điểm ở giới hạn độ sâu là ước lượng, không phải xác suất thắng.</p><p>Đã gọi tìm kiếm {{ result.counts.calls }} lần, dùng lại {{ result.counts.cacheHits }} kết quả chính xác và có {{ result.counts.cutoffs }} lần dừng theo cửa sổ. Mỗi nước gốc được đánh giá với cửa sổ đầy đủ để các điểm trong danh sách đều so sánh được.</p></section></div>
 <details class="ttt-eval"><summary>Hàm đánh giá và các đặc trưng</summary><p>Ở trạng thái chưa kết thúc, một hàng, cột hoặc đường chéo chỉ có X được cộng điểm, chỉ có O bị trừ điểm. Đường có cả hai hoặc chưa có quân nhận 0. Trạng thái kết thúc luôn dùng lợi ích thật trước bước đánh giá.</p><label>Trọng số đường có một quân<input v-model.number="w1" type="range" min="0" max="8"/>{{ w1 }}</label><label>Trọng số đường có hai quân<input v-model.number="w2" type="range" min="0" max="8"/>{{ w2 }}</label><p>Tổng điểm hiện tại: {{ features.map(f=>f.value).join(' + ') }} = {{ features.reduce((s,f)=>s+f.value,0) }}.</p><ul><li v-for="f in features" :key="f.id">Đường {{ f.id }} (Ô {{ f.cells.map(c=>c+1).join(', ') }}): {{ f.x }} quân X, {{ f.o }} quân O, điểm {{ f.value }}.</li></ul><p>Khi độ sâu đủ để tới mọi trạng thái kết thúc, đổi trọng số không đổi giá trị trò chơi. Ở độ sâu nông, trọng số có thể đổi nước được đề nghị.</p></details>
 <details class="ttt-edit"><summary>Nhập thế cờ khác</summary><p>Nhập chín ký tự X, O hoặc dấu chấm cho ô trống, đọc theo hàng. Chỉ nhận thế cờ hợp lệ với X đi trước.</p><label>Thế cờ<input v-model="input" type="text" maxlength="30" spellcheck="false"/></label><button type="button" @click="apply">Áp dụng thế cờ</button><p v-if="error" role="alert">{{ error }}</p></details>
 <details class="ttt-code"><summary>Mã JavaScript của bộ giải đang chạy</summary><button type="button" @click="copy">{{ copied?'Đã chép mã':'Chép bộ giải' }}</button><p>Mã xuất các hàm kiểm tra trạng thái, đánh giá và phân tích từng nước. Lưu thành tic-tac-toe.mjs rồi nhập analyzeTicTacToe để dùng với Node.js hoặc trình duyệt hỗ trợ module.</p><pre><code><span v-for="(row,i) in ticTacToeSource.split('\n')" :key="i" class="ttt-code-row"><span aria-hidden="true" class="line-number">{{ i+1 }}</span><span><span v-for="(t,j) in tokens(row)" :key="j" :class="t.kind">{{ t.text }}</span></span></span></code></pre></details>
 <details class="lab-tasks"><summary>Thử và giải thích lựa chọn</summary><ol><li>Ở bàn trống, cho cả hai bên đi nước đề nghị đến hết ván. Kết quả có phù hợp với giá trị ban đầu không?</li><li>Chọn thế “O cần chặn hàng của X”. Vì sao O vẫn phải tối thiểu hóa điểm của X?</li><li>Giảm độ sâu rồi thay trọng số. Sau đó tăng độ sâu đủ tới cuối ván và so sánh.</li></ol></details>
</figure>
</template>

<style scoped>
.ttt-code pre{white-space:pre-wrap;overflow-wrap:anywhere;overflow:visible;background:var(--paper);border:1px solid var(--rule);border-radius:var(--radius);padding:12px;font:13px/1.8 var(--font-code);color:var(--ink)}.ttt-code code{font:inherit}.ttt-code-row{display:grid;grid-template-columns:3ch minmax(0,1fr);gap:8px}.line-number{user-select:none;color:var(--ink-2)}.keyword{color:var(--tim);font-weight:600}.string{color:var(--xanh)}.number{color:var(--do)}
</style>

<style scoped>
.ttt-lab{min-width:0}.ttt-settings{display:grid;grid-template-columns:1fr 1fr;gap:12px}.ttt-lab label{display:grid;gap:6px;font:var(--fs-small)/1.7 var(--font-ui)}.ttt-settings label:last-child{grid-column:1/-1}.ttt-lab :is(button,select,input){min-height:44px;max-width:100%;box-sizing:border-box;font:var(--fs-small)/1.6 var(--font-ui);background:var(--paper);color:var(--ink);border:1px solid var(--control);border-radius:var(--radius);padding:8px}.ttt-lab select,.ttt-edit input,.ttt-lab input[type=range]{width:100%}.ttt-lab :is(button,select,input):focus-visible{outline:3px solid var(--tim);outline-offset:3px}.ttt-lab button,.ttt-lab summary{cursor:pointer}.ttt-status{padding:12px;background:var(--tim-soft);border-left:3px solid var(--tim)}.ttt-panels{display:grid;grid-template-columns:1fr 1fr;gap:20px}.ttt-panels section{min-width:0}.ttt-lab h4{font:600 var(--fs-ui)/1.7 var(--font-ui);margin:0 0 12px}.ttt-board{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:6px;max-width:280px;aspect-ratio:1}.ttt-board button{font:600 28px var(--font-ui);padding:0}.ttt-board button:disabled{opacity:1;cursor:default}.ttt-board .recommended{border:2px solid var(--tim);background:var(--tim-soft)}.ttt-board .winning{background:var(--tim);color:var(--paper)}.ttt-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}.ttt-lab p,.ttt-lab li{font:var(--fs-small)/1.7 var(--font-ui);overflow-wrap:anywhere}.ttt-lab details{margin-top:16px;font-size:var(--fs-small)}.ttt-lab summary{min-height:44px;line-height:1.7}.ttt-eval label{margin-top:12px}.ttt-edit button{margin-top:10px}.ttt-lab button:disabled{cursor:default}.ttt-lab .ttt-actions button:disabled{opacity:.55}@media(max-width:700px){.ttt-panels,.ttt-settings{grid-template-columns:minmax(0,1fr)}.ttt-lab{padding:12px}.ttt-board{max-width:240px}}
</style>
